-- Migration 156: Fix retro evaluation of TRIM/EXIT recommendations
-- Adds TRIM/EXIT evaluation rules + few-shot examples to retro_evaluator
-- Adds TRIM/EXIT performance assessment rules to retro_generator

-- retro_evaluator: Add TRIM/EXIT evaluation rules
UPDATE agent_prompts
SET system_prompt = system_prompt || E'\n\n## TRIM/EXIT Evaluation Rules\n\nFor TRIM or EXIT recommendations on existing positions:\n- `P/L` = unrealized profit from original entry price (informational only)\n- `day` = today''s price change from previous close (this is the performance metric)\n- `prev` = previous trading day''s close price\n\nEvaluation logic:\n1. If TRIM/EXIT was recommended AND NOT executed (no matching closed trade):\n   - If day_change < -3%: EXECUTION_ERROR — \"TRIM recommended but not executed, stock dropped {day}%\"\n   - If day_change between -3% and 0%: VARIANCE — minor adverse move\n   - If day_change >= 0%: N/A — ignoring TRIM was acceptable\n2. If TRIM/EXIT was executed (confirmed by tool_get_executed_trades):\n   - WIN if stock continued dropping after exit\n   - HOLD if stock recovered (exit was premature)\n\nCRITICAL: Do NOT use P/L from entry to evaluate TRIM/EXIT accuracy.\nA +7.3% unrealized gain does NOT make an ignored TRIM correct when the stock dropped 7% today.\nThe RECOMMENDATION is evaluated by today''s outcome, not the position''s lifetime P/L.\n\n## Price Context Fields\n- `prev:{price}` = previous day''s close. Use this to assess gap-ups/downs at open.\n- `day:{pct}%` = change from PREVIOUS CLOSE (not from today''s open). Includes overnight gaps.\n- `P/L:{pct}%` = unrealized P/L from position entry price. Do NOT use for recommendation accuracy.\n\n<good_example>\nVHM TRIM: TRIM recommended but not executed [day:-6.9%, prev:108k to EOD:100.5k]. Position still +7.3% from 93k entry but gave back 7.5k/share today.\nerror_type: EXECUTION_ERROR\nlesson: Execute TRIM when midday confirms HIGH priority — 7% gap-down proves the signal was correct.\n</good_example>\n\n<bad_example>\nVHM TRIM: Position held, still profitable at +7.3%. No error in thesis.\nerror_type: N/A\nBad because: Uses unrealized P/L (+7.3%) to evaluate TRIM accuracy. Ignores -6.9% daily drop. The TRIM recommendation was correct — not executing it was the error.\n</bad_example>'
WHERE agent_key = 'retro_evaluator'
  AND system_prompt NOT LIKE '%TRIM/EXIT Evaluation Rules%';

-- retro_generator: Add TRIM/EXIT performance assessment rules
UPDATE agent_prompts
SET system_prompt = system_prompt || E'\n\n## TRIM/EXIT Performance Assessment\n- For TRIM/EXIT recommendations, assess using `day` change (from prev close), NOT `P/L` from entry\n- If TRIM was recommended and ignored while stock dropped >3%: this is a MISS, not a HIT\n- FORBIDDEN: Listing an unexecuted TRIM as a HIT when the stock dropped significantly\n- FORBIDDEN: Citing unrealized P/L from entry as evidence of \"outperformance\" on a down day\n  Bad: \"Real estate (VHM +7.3%) outperformed\" when VHM dropped 7% today\n  Good: \"Real estate (VHM day:-6.9%) worst performer, TRIM signal was correct but unexecuted\"'
WHERE agent_key = 'retro_generator'
  AND system_prompt NOT LIKE '%TRIM/EXIT Performance Assessment%';
